const clone=x=>JSON.parse(JSON.stringify(x));const cash=x=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(x);const ml=m=>new Date(m+'-02T12:00:00').toLocaleDateString('en-US',{month:'short',year:'numeric'});const uid=()=>crypto.randomUUID();const KEY='uab-grant-react-v1';
