function download(data,name){const a=document.createElement('a');a.href=URL.createObjectURL(data instanceof Blob?data:new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
const EditingContext=React.createContext(false);
function MutationButton(props){const editing=React.useContext(EditingContext);return editing?<Button {...props}/>:null}
function Checkbox(props){const editing=React.useContext(EditingContext);return editing?<BaseCheckbox {...props}/>:<span aria-label={props['aria-label']}>{props.checked?'Yes':'No'}</span>}
function BudgetSelect(props){const editing=React.useContext(EditingContext);if(editing)return <select {...props}/>;const selected=React.Children.toArray(props.children).find((child:any)=>String(child.props?.value??child.props?.children)===String(props.value));return <span className="read-value" aria-label={props['aria-label']}>{React.isValidElement(selected)?(selected.props as any).children:props.value??'—'}</span>}
function Field({value,onCommit,label,type='text',nullable=false,currency=false,...props}){const [draft,setDraft]=useState(value??''),[message,setMessage]=useState('');const errorId=useId();const editing=React.useContext(EditingContext);useEffect(()=>setDraft(value??''),[value]);if(!editing)return <span className={currency?"read-value money-value":"read-value"} aria-label={label}>{value===null||value===undefined||value===''?(props.placeholder??'—'):type==='month'?ml(value):type==='date'?value.slice(5,7)+'/'+value.slice(8,10)+'/'+value.slice(0,4):currency?cash(value):String(value)}</span>;return <div><Input aria-label={label} aria-invalid={!!message} aria-describedby={message?errorId:undefined} type={type} value={draft} onChange={e=>{setDraft(e.target.value);setMessage('')}} onBlur={e=>{try{const entered=e.currentTarget.value;const next=type==='number'?numericFieldValue(entered,nullable):entered;if(next!==value&&onCommit(next)===false)setDraft(value??'')}catch(e){setMessage(e.message);setDraft(value??'')}}} onKeyDown={e=>{if(e.key==='Enter')e.currentTarget.blur();if(e.key==='Escape'){setDraft(value??'');setMessage('')}}} {...props}/>{message&&<p id={errorId} role="alert" className="field-error">{message}</p>}</div>}

function Grid({headers,rows,label}){return <ScrollableTable label={label} className={["Team","Raises","Assignment","Personnel cost summary"].includes(label)?"mobile-records":""}><Table scrollContainer={false}><TableHeader><TableRow>{headers.map((h,i)=><TableHead key={i}>{h}</TableHead>)}</TableRow></TableHeader><TableBody>{rows.map((r,i)=><TableRow key={r.key??i}>{(r.cells??r).map((v,j)=><TableCell key={j} data-label={headers[j]}>{v}</TableCell>)}</TableRow>)}</TableBody></Table></ScrollableTable>}
