 const commit=(fn,action='Budget edited')=>{if(!editSession.active){setError('Choose Edit to change the budget.');return false}try{const next=editSession.update(archive=>{const before=clone(archive.project);fn(archive.project);if(JSON.stringify(archive.project.ledger)!==JSON.stringify(before.ledger)||JSON.stringify(archive.project.subPays)!==JSON.stringify(before.subPays)||['start','end','asOf','source','mode'].some(k=>archive.project.grant[k]!==before.grant[k]))archive.project.grant.reconciled=false},validateProject);currentArchive.current=next;setS(next.project);setError('');return true}catch(err){setError(err.message);return false}};
