 const remove=(list,index)=>{if(list==='commitments'&&s.ledger.some(e=>e.commitmentId===s.commitments[index].id)){setError('This commitment has payment history. Cancel the remaining balance instead.');return;}if(list==='ledger'&&(s.ledger[index].reversalOf!==undefined||s.ledger.some(r=>String(r.reversalOf)===String(s.ledger[index].id)))){setError('Linked reversals and their original transactions must remain together.');return;}if(list==='subawards'&&!confirm('Remove this subaward and its payments?'))return;if(list==='people'&&s.ledger.some(e=>e.personId===s.people[index].id)){setError('This person has payroll history. Set future effort to zero instead.');return}commit(n=>{const row=n[list][index];n[list].splice(index,1);if(list==='subawards')n.subPays=n.subPays.filter(p=>String(p.sub)!==String(row.id))},'Removed '+list)};
